From e42402a83871151a4e367995ecfd2d9dd5c699ae Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 23:12:42 +0100
Subject: [PATCH] kded: explain failed enterprise authentication in the
 password dialog

When 802.1X authentication failed, the dialog asking again for secrets
said the password was wrong, even when the cause was a wrong EAP method,
CA certificate or domain. It now names those too and offers Configure.

BUG: 459713
---
 kded/passworddialog.cpp | 28 +++++++++++++++++++++++++++-
 1 file changed, 27 insertions(+), 1 deletion(-)

diff --git a/kded/passworddialog.cpp b/kded/passworddialog.cpp
index ae796b7ee..83bd3edec 100644
--- a/kded/passworddialog.cpp
+++ b/kded/passworddialog.cpp
@@ -16,6 +16,7 @@
 #include <NetworkManagerQt/VpnSetting>
 #include <NetworkManagerQt/WirelessSetting>

+#include <KIO/CommandLauncherJob>
 #include <KLocalizedString>

 #include <QIcon>
@@ -93,7 +94,32 @@ void PasswordDialog::initializeUi()

         WirelessSetting::Ptr wifi = m_connectionSettings->setting(Setting::Wireless).dynamicCast<WirelessSetting>();
         Setting::SettingType connectionType = setting->type();
-        if (wifi && (connectionType == Setting::WirelessSecurity || connectionType == Setting::Security8021x)) {
+        if (connectionType == Setting::Security8021x && (m_flags & NetworkManager::SecretAgent::RequestNew)) {
+            if (wifi) {
+                m_ui->labelText->setText(
+                    i18n("Could not authenticate to the Wi-Fi network \"%1\". Check the password and the network's security settings, "
+                         "such as the authentication method, CA certificate and domain.",
+                         QString::fromUtf8(wifi->ssid())));
+            } else {
+                m_ui->labelText->setText(
+                    i18n("Could not authenticate to the connection \"%1\". Check the password and the connection's security settings, "
+                         "such as the authentication method, CA certificate and domain.",
+                         m_connectionSettings->id()));
+            }
+
+            if (!m_connectionSettings->uuid().isEmpty()) {
+                QPushButton *configureButton = m_ui->buttonBox->addButton(i18nc("@action:button", "Configure…"), QDialogButtonBox::ActionRole);
+                configureButton->setIcon(QIcon::fromTheme(QStringLiteral("configure")));
+                connect(configureButton, &QPushButton::clicked, this, [this] {
+                    auto job = new KIO::CommandLauncherJob(
+                        QStringLiteral("systemsettings"),
+                        {QStringLiteral("kcm_networkmanagement"), QStringLiteral("--args"), QStringLiteral("Uuid=") + m_connectionSettings->uuid()});
+                    job->setDesktopName(QStringLiteral("systemsettings"));
+                    job->start();
+                    reject();
+                });
+            }
+        } else if (wifi && (connectionType == Setting::WirelessSecurity || connectionType == Setting::Security8021x)) {
             const QString ssid = QString::fromUtf8(wifi->ssid());
             if (m_flags & NetworkManager::SecretAgent::RequestNew) {
                 m_ui->labelText->setText(i18n("Incorrect password for the Wi-Fi network \"%1\". Please try again.", ssid));
-- 
